type Limiter struct {
    counts    map[string]int
    limit     int
    allowlist map[string]bool
    mu        sync.Mutex
}

func (l *Limiter) Allow(key string) bool {
    l.mu.Lock()
    defer l.mu.Unlock()
    if l.allowlist[key] {
        return true
    }
    l.counts[key]++
    return l.counts[key] <= l.limit
}

except Exception as exc:
        db.rollback()
        raise HTTPException(status_code=status.HTTP_500_INTERNAL_SERVER_ERROR, detail="Failed to create refund") from exc
